        // -- The accountless screen ----------------------------------------
        //
        // Ported from the console's `pub.*` rows rather than translated
        // again: one product says one thing, and a second translation of the
        // same sentence is a second thing to keep in step. The four keys the
        // console has no row for name UI only a shell has — a sheet's dismiss
        // button, two client-side validation lines and a placeholder.
        "pub.sub" to mapOf("en" to "Without an account", "es" to "Sin cuenta", "fr" to "Sans compte", "de" to "Ohne Konto", "pt" to "Sem conta", "it" to "Senza account", "ja" to "アカウントなしで", "zh" to "无需账户", "hi" to "बिना खाते के", "ar" to "بدون حساب"),
        "pub.invite" to mapOf("en" to "Here about a profile, not for one?", "es" to "¿Viene por un perfil, no a crear uno?", "fr" to "Ici à propos d'un profil, pas pour en créer un ?", "de" to "Wegen eines Profils hier, nicht für eines?", "pt" to "Está aqui por causa de um perfil, não para criar um?", "it" to "Sei qui per un profilo, non per crearne uno?", "ja" to "プロフィールを作りに来たのではなく、あるプロフィールの件でしょうか？", "zh" to "你是为某个资料而来，而不是来创建一个？", "hi" to "किसी प्रोफ़ाइल के बारे में आए हैं, बनाने नहीं?", "ar" to "أتيت بشأن ملف، لا لإنشاء واحد؟"),
        "pub.invite.none" to mapOf("en" to "Neither needs an account.", "es" to "Ninguna de las dos necesita cuenta.", "fr" to "Aucun des deux ne nécessite de compte.", "de" to "Für beides ist kein Konto nötig.", "pt" to "Nenhuma das duas precisa de conta.", "it" to "Nessuna delle due richiede un account.", "ja" to "どちらもアカウントは不要です。", "zh" to "两者都不需要账户。", "hi" to "दोनों के लिए खाता ज़रूरी नहीं।", "ar" to "لا يحتاج أيٌّ منهما إلى حساب."),
        "pub.object.title" to mapOf("en" to "A profile depicts me", "es" to "Un perfil me representa", "fr" to "Un profil me représente", "de" to "Ein Profil stellt mich dar", "pt" to "Um perfil representa-me", "it" to "Un profilo mi rappresenta", "ja" to "私を模したプロフィールがあります", "zh" to "有一个资料在描绘我", "hi" to "एक प्रोफ़ाइल मुझे दर्शाती है", "ar" to "هناك ملف يصوّرني"),
        "pub.tab.mark" to mapOf("en" to "Is this genuine?", "es" to "¿Esto es auténtico?", "fr" to "Est-ce authentique ?", "de" to "Ist das echt?", "pt" to "Isto é genuíno?", "it" to "È autentico?", "ja" to "これは本物ですか？", "zh" to "这是真的吗？", "hi" to "क्या यह असली है?", "ar" to "هل هذا أصلي؟"),
        "pub.object.restricts" to mapOf("en" to "You do not need an account, and this page is the proof of it rather than a promise about it. Opening an objection restricts the profile straight away — public surfaces off, no new interactors — before anybody reviews it.", "es" to "No necesita una cuenta, y esta página es la prueba de ello, no una promesa al respecto. Abrir una objeción restringe el perfil de inmediato —superficies públicas desactivadas, sin nuevos interlocutores— antes de que nadie lo revise.", "fr" to "Vous n'avez pas besoin de compte, et cette page en est la preuve plutôt qu'une promesse. Ouvrir une contestation restreint le profil immédiatement — surfaces publiques coupées, aucun nouvel interlocuteur — avant tout examen.", "de" to "Sie brauchen kein Konto, und diese Seite ist der Beweis dafür statt eines Versprechens darüber. Ein Widerspruch beschränkt das Profil sofort — öffentliche Flächen aus, keine neuen Gesprächspartner — noch bevor jemand es prüft.", "pt" to "Não precisa de conta, e esta página é a prova disso e não uma promessa sobre isso. Abrir uma contestação restringe o perfil de imediato — superfícies públicas desligadas, sem novos interlocutores — antes de alguém a analisar.", "it" to "Non serve un account, e questa pagina ne è la prova anziché una promessa. Aprire una contestazione limita subito il profilo — superfici pubbliche spente, nessun nuovo interlocutore — prima che qualcuno la esamini.", "ja" to "アカウントは不要です。このページはその約束ではなく、その証拠です。異議を申し立てると、誰かが審査する前に、プロフィールは直ちに制限されます（公開面は停止、新しい相手とのやり取りも停止）。", "zh" to "你不需要账户，本页面就是证明，而不是关于它的承诺。提出异议会立即限制该资料 — 关闭公开界面、不再接受新的互动对象 — 在任何人审核之前。", "hi" to "आपको खाते की ज़रूरत नहीं, और यह पृष्ठ उसका वादा नहीं बल्कि प्रमाण है। आपत्ति दर्ज करते ही प्रोफ़ाइल तुरंत सीमित हो जाती है — सार्वजनिक सतहें बंद, कोई नया संवादकर्ता नहीं — किसी की समीक्षा से पहले।", "ar" to "لا تحتاج إلى حساب، وهذه الصفحة هي الدليل على ذلك لا وعدًا به. فتح اعتراض يقيّد الملف فورًا — إيقاف الواجهات العامة، ولا متفاعلين جدد — قبل أن يراجعه أحد."),
        "pub.object.profileId" to mapOf("en" to "the profile's id", "es" to "el id del perfil", "fr" to "l'identifiant du profil", "de" to "die ID des Profils", "pt" to "o id do perfil", "it" to "l'id del profilo", "ja" to "プロフィールのID", "zh" to "该资料的 id", "hi" to "प्रोफ़ाइल की आईडी", "ar" to "معرّف الملف"),
        "pub.object.ref" to mapOf("en" to "your proof reference", "es" to "su referencia de prueba", "fr" to "votre référence de preuve", "de" to "Ihr Nachweis-Aktenzeichen", "pt" to "a sua referência de prova", "it" to "il tuo riferimento di prova", "ja" to "本人確認の参照番号", "zh" to "你的证明编号", "hi" to "आपका प्रमाण संदर्भ", "ar" to "مرجع إثباتك"),
        "pub.object.reason" to mapOf("en" to "why — in your own words", "es" to "por qué — con sus palabras", "fr" to "pourquoi — avec vos mots", "de" to "warum — in Ihren eigenen Worten", "pt" to "porquê — nas suas palavras", "it" to "perché — con parole tue", "ja" to "理由 — ご自身の言葉で", "zh" to "原因 — 用你自己的话", "hi" to "क्यों — अपने शब्दों में", "ar" to "لماذا — بكلماتك"),
        "pub.object.ref.note" to mapOf("en" to "The proof reference points at an identity check held outside this system — it is not a login, and it is what lets you object without one.", "es" to "La referencia de prueba apunta a una comprobación de identidad realizada fuera de este sistema: no es un inicio de sesión, y es lo que le permite objetar sin tener uno.", "fr" to "La référence de preuve renvoie à une vérification d'identité effectuée hors de ce système : ce n'est pas une connexion, et c'est ce qui vous permet de contester sans en avoir une.", "de" to "Das Nachweis-Aktenzeichen verweist auf eine Identitätsprüfung außerhalb dieses Systems — es ist keine Anmeldung, und genau deshalb können Sie ohne eine widersprechen.", "pt" to "A referência de prova aponta para uma verificação de identidade feita fora deste sistema: não é um início de sessão, e é o que lhe permite contestar sem ter um.", "it" to "Il riferimento di prova rimanda a una verifica d'identità tenuta fuori da questo sistema: non è un accesso, ed è ciò che ti permette di contestare senza averne uno.", "ja" to "参照番号は、この仕組みの外で行われた本人確認を指します。ログインではなく、ログインなしで異議を申し立てられるようにするためのものです。", "zh" to "证明编号指向在本系统之外完成的身份核验 — 它不是登录凭据，正是它让你无需登录也能提出异议。", "hi" to "प्रमाण संदर्भ इस प्रणाली के बाहर हुई पहचान-जाँच की ओर इशारा करता है — यह लॉगिन नहीं है, और यही आपको बिना लॉगिन के आपत्ति दर्ज करने देता है।", "ar" to "مرجع الإثبات يشير إلى تحقّق من الهوية جرى خارج هذا النظام — ليس تسجيل دخول، وهو ما يتيح لك الاعتراض بدونه."),
        "pub.object.open" to mapOf("en" to "Open it", "es" to "Abrirla", "fr" to "L'ouvrir", "de" to "Einreichen", "pt" to "Abrir", "it" to "Aprila", "ja" to "申し立てる", "zh" to "提出", "hi" to "दर्ज करें", "ar" to "افتحه"),
        "pub.object.opened" to mapOf("en" to "Opened — {id}", "es" to "Abierta — {id}", "fr" to "Ouverte — {id}", "de" to "Eröffnet — {id}", "pt" to "Aberta — {id}", "it" to "Aperta — {id}", "ja" to "受付済み — {id}", "zh" to "已提出 — {id}", "hi" to "दर्ज — {id}", "ar" to "فُتح — {id}"),
        "pub.object.opened.status" to mapOf("en" to "The profile is {now} from this moment. It was {before}, and if the objection is dismissed it goes back to exactly that.", "es" to "El perfil queda {now} desde este momento. Era {before}, y si la objeción se desestima vuelve exactamente a eso.", "fr" to "Le profil est {now} à partir de maintenant. Il était {before}, et si la contestation est rejetée il y revient exactement.", "de" to "Das Profil ist ab sofort {now}. Es war {before}, und wenn der Widerspruch abgewiesen wird, kehrt es genau dorthin zurück.", "pt" to "O perfil fica {now} a partir deste momento. Era {before}, e se a contestação for rejeitada volta exatamente a isso.", "it" to "Il profilo è {now} da questo momento. Era {before}, e se la contestazione viene respinta torna esattamente a quello.", "ja" to "プロフィールはこの時点から {now} になります。それまでは {before} でした。異議が棄却されれば、そのままの状態に戻ります。", "zh" to "该资料从此刻起为 {now}。此前是 {before}；若异议被驳回，将完全恢复原状。", "hi" to "इस क्षण से प्रोफ़ाइल {now} है। यह {before} थी, और यदि आपत्ति खारिज होती है तो वह ठीक वैसी ही हो जाएगी।", "ar" to "الملف {now} اعتبارًا من هذه اللحظة. كان {before}، وإذا رُفض الاعتراض عاد إلى ذلك تمامًا."),
        "pub.object.writeitdown" to mapOf("en" to "Write the id down. It is how you check this case later without an account — there is no inbox here to come back to.", "es" to "Anote el identificador. Es cómo consultará este caso más adelante sin una cuenta: aquí no hay bandeja de entrada a la que volver.", "fr" to "Notez l'identifiant. C'est ainsi que vous suivrez ce dossier plus tard sans compte : il n'y a pas de boîte de réception ici où revenir.", "de" to "Notieren Sie die ID. So prüfen Sie diesen Fall später ohne Konto — hier gibt es keinen Posteingang, zu dem Sie zurückkehren könnten.", "pt" to "Anote o id. É assim que consultará este caso mais tarde sem conta — aqui não há caixa de entrada para onde voltar.", "it" to "Annota l'id. È così che controllerai questo caso più avanti senza un account: qui non c'è una casella a cui tornare.", "ja" to "IDを控えてください。アカウントなしで後からこの件を確認する唯一の方法です。戻ってこられる受信箱はありません。", "zh" to "请记下这个 id。这是你日后在没有账户的情况下查询本案的方式 — 这里没有可供你回来查看的收件箱。", "hi" to "यह आईडी लिख लें। बिना खाते के बाद में इस मामले को देखने का यही तरीका है — यहाँ लौटने के लिए कोई इनबॉक्स नहीं है।", "ar" to "دوّن المعرّف. فهو كيف تتابع هذه القضية لاحقًا بدون حساب — لا يوجد هنا صندوق وارد تعود إليه."),
        "pub.mark.title" to mapOf("en" to "Somebody sent me this", "es" to "Alguien me envió esto", "fr" to "Quelqu'un m'a envoyé ceci", "de" to "Jemand hat mir das geschickt", "pt" to "Alguém enviou-me isto", "it" to "Qualcuno mi ha mandato questo", "ja" to "これを送られてきました", "zh" to "有人给我发了这个", "hi" to "किसी ने मुझे यह भेजा", "ar" to "أرسل لي أحدهم هذا"),
        "pub.mark.explain" to mapOf("en" to "Paste it. This asks whose work it is with no credential id, and keeps answering after the text has been reworded — which is the state text usually arrives in. It is the right question for a stranger holding a screenshot; checking a credential you already hold is a different one and lives inside an account.", "es" to "Péguelo. Esto pregunta de quién es el trabajo sin ningún identificador de credencial, y sigue respondiendo después de que el texto haya sido reescrito, que es el estado en el que suele llegar. Es la pregunta correcta para un desconocido con una captura de pantalla; comprobar una credencial que ya tiene es otra distinta y vive dentro de una cuenta.", "fr" to "Collez-le. Ceci demande à qui appartient le contenu sans aucun identifiant de justificatif, et répond encore après reformulation du texte — l'état dans lequel il arrive le plus souvent. C'est la bonne question pour un inconnu tenant une capture d'écran ; vérifier un justificatif que vous détenez déjà en est une autre, et elle vit dans un compte.", "de" to "Fügen Sie ihn ein. Das fragt, wessen Werk es ist, ohne jede Credential-ID, und antwortet auch noch, nachdem der Text umformuliert wurde — der Zustand, in dem Text meist ankommt. Es ist die richtige Frage für eine fremde Person mit einem Screenshot; ein Nachweis, den Sie bereits halten, ist eine andere Frage und lebt in einem Konto.", "pt" to "Cole-o. Isto pergunta de quem é o trabalho sem qualquer identificador de credencial, e continua respondendo depois de o texto ter sido reescrito — o estado em que o texto costuma chegar. É a pergunta certa para um desconhecido com uma captura de tela; verificar uma credencial que você já possui é outra e vive dentro de uma conta.", "it" to "Incollalo. Questo chiede di chi è il lavoro senza alcun identificativo di credenziale, e continua a rispondere dopo che il testo è stato riformulato — lo stato in cui il testo di solito arriva. È la domanda giusta per uno sconosciuto con uno screenshot; verificare una credenziale che già possiedi è un'altra cosa e vive dentro un account.", "ja" to "貼り付けてください。これは資格情報の ID なしに、それが誰の作かを尋ねます。文章が書き換えられた後でも答え続けます — 実際に届く文章はたいていその状態です。スクリーンショットを手にした見知らぬ人にとって正しい問いです。すでに持っている資格情報を確認するのは別の問いで、それはアカウントの中にあります。", "zh" to "粘贴进来。这会在不需要任何凭据 ID 的情况下询问它出自谁手，并且在文本被改写之后仍能作答 — 而文本通常正是以这种状态出现的。对于手持截图的陌生人，这是正确的问题；核验你已经持有的凭据是另一个问题，它属于账户内部。", "hi" to "इसे चिपकाएँ। यह बिना किसी क्रेडेंशियल आईडी के पूछता है कि यह किसका काम है, और पाठ के शब्द बदल दिए जाने के बाद भी उत्तर देता रहता है — पाठ आम तौर पर इसी हालत में पहुँचता है। स्क्रीनशॉट थामे किसी अजनबी के लिए यही सही सवाल है; जो क्रेडेंशियल आपके पास पहले से है उसे जाँचना अलग सवाल है और वह खाते के भीतर रहता है।", "ar" to "الصقه هنا. هذا يسأل عن صاحب العمل دون أي معرّف اعتماد، ويظل يجيب بعد إعادة صياغة النص — وهي الحالة التي يصل بها النص عادةً. إنه السؤال الصحيح لغريب يحمل لقطة شاشة؛ أما التحقق من اعتماد تملكه بالفعل فسؤال آخر يعيش داخل حساب."),
        "pub.mark.paste" to mapOf("en" to "paste the text", "es" to "pegue el texto", "fr" to "collez le texte", "de" to "Text einfügen", "pt" to "cole o texto", "it" to "incolla il testo", "ja" to "テキストを貼り付けてください", "zh" to "粘贴文本", "hi" to "पाठ चिपकाएँ", "ar" to "الصق النص"),
        "pub.mark.ask" to mapOf("en" to "Ask who wrote it", "es" to "Preguntar quién lo escribió", "fr" to "Demander qui l'a écrit", "de" to "Fragen, wer es geschrieben hat", "pt" to "Perguntar quem o escreveu", "it" to "Chiedi chi l'ha scritto", "ja" to "誰が書いたか調べる", "zh" to "查询是谁写的", "hi" to "पूछें किसने लिखा", "ar" to "اسأل من كتبه"),
        "pub.mark.producedby" to mapOf("en" to "Produced by a QRME synthetic profile — {state}.", "es" to "Producido por un perfil sintético de QRME — {state}.", "fr" to "Produit par un profil synthétique QRME — {state}.", "de" to "Erzeugt von einem synthetischen QRME-Profil — {state}.", "pt" to "Produzido por um perfil sintético do QRME — {state}.", "it" to "Prodotto da un profilo sintetico QRME — {state}.", "ja" to "QRME の合成プロフィールによる生成物 — {state}。", "zh" to "由 QRME 合成资料生成 — {state}。", "hi" to "QRME की सिंथेटिक प्रोफ़ाइल द्वारा निर्मित — {state}।", "ar" to "من إنتاج ملف اصطناعي في QRME — {state}."),
        "pub.mark.windows" to mapOf("en" to "{matched} of {stored} stored windows matched, out of {examined} examined (similarity {similarity}).", "es" to "Coincidieron {matched} de {stored} ventanas almacenadas, de {examined} examinadas (similitud {similarity}).", "fr" to "{matched} fenêtres enregistrées sur {stored} correspondent, sur {examined} examinées (similarité {similarity}).", "de" to "{matched} von {stored} gespeicherten Fenstern stimmten überein, bei {examined} geprüften (Ähnlichkeit {similarity}).", "pt" to "Coincidiram {matched} de {stored} janelas armazenadas, entre {examined} examinadas (similaridade {similarity}).", "it" to "Hanno corrisposto {matched} finestre su {stored} memorizzate, su {examined} esaminate (somiglianza {similarity}).", "ja" to "保存済み {stored} 個のウィンドウのうち {matched} 個が一致しました（検査対象 {examined} 個、類似度 {similarity}）。", "zh" to "在 {examined} 个受检窗口中，已存储的 {stored} 个窗口有 {matched} 个匹配（相似度 {similarity}）。", "hi" to "संग्रहीत {stored} विंडो में से {matched} मेल खाईं, कुल {examined} जाँची गईं (समानता {similarity})।", "ar" to "تطابقت {matched} من أصل {stored} نافذة مخزّنة، من بين {examined} جرى فحصها (التشابه {similarity})."),
        "pub.mark.altered" to mapOf("en" to "The wording has changed since it was stamped. That does not make it less traceable — it is what the score above is measuring.", "es" to "La redacción ha cambiado desde que se selló. Eso no lo hace menos rastreable: es precisamente lo que mide la puntuación anterior.", "fr" to "La formulation a changé depuis l'horodatage. Cela ne le rend pas moins traçable : c'est justement ce que mesure le score ci-dessus.", "de" to "Der Wortlaut hat sich seit der Kennzeichnung geändert. Das macht ihn nicht weniger nachverfolgbar — genau das misst der Wert oben.", "pt" to "A redação mudou desde que foi selada. Isso não a torna menos rastreável: é precisamente o que a pontuação acima mede.", "it" to "Il testo è cambiato da quando è stato marcato. Questo non lo rende meno tracciabile: è proprio ciò che il punteggio sopra misura.", "ja" to "刻印されてから文言が変わっています。それで追跡できなくなるわけではありません。上のスコアが測っているのはまさにその差です。", "zh" to "自加盖标记以来措辞已经改变。这并不会让它更难追溯 — 上面的分数衡量的正是这一点。", "hi" to "मुहर लगने के बाद शब्द बदले हैं। इससे यह कम पता लगाने योग्य नहीं होता — ऊपर का स्कोर यही माप रहा है।", "ar" to "تغيّرت الصياغة منذ ختمه. هذا لا يجعله أقل قابلية للتتبّع — فذلك تحديدًا ما تقيسه الدرجة أعلاه."),
        "pub.mark.unknown" to mapOf("en" to "Not recognised", "es" to "No reconocido", "fr" to "Non reconnu", "de" to "Nicht erkannt", "pt" to "Não reconhecido", "it" to "Non riconosciuto", "ja" to "該当なし", "zh" to "未识别", "hi" to "पहचाना नहीं गया", "ar" to "غير معروف"),
        "pub.mark.unknown.explain" to mapOf("en" to "This says nothing about whether a person wrote it. It says no profile {here} has stamped work that shares enough wording with it.", "es" to "Esto no dice nada sobre si lo escribió una persona. Dice que ningún perfil {here} ha firmado un trabajo que comparta suficiente redacción con él.", "fr" to "Cela ne dit rien sur le fait qu'une personne l'ait écrit. Cela dit qu'aucun profil {here} n'a signé un contenu partageant assez de formulations avec lui.", "de" to "Das sagt nichts darüber, ob ein Mensch es geschrieben hat. Es sagt, dass kein Profil {here} eine Arbeit gestempelt hat, die genug Wortlaut mit ihr teilt.", "pt" to "Isto não diz nada sobre se uma pessoa o escreveu. Diz que nenhum perfil {here} carimbou um trabalho que partilhe redação suficiente com ele.", "it" to "Questo non dice nulla sul fatto che l'abbia scritto una persona. Dice che nessun profilo {here} ha timbrato un lavoro che condivida abbastanza formulazioni con esso.", "ja" to "これは人が書いたかどうかについては何も述べていません。{here}、これと十分に語句を共有する作品に印を付けたプロフィールが存在しない、という意味です。", "zh" to "这并不说明它是否由人所写。它说明的是：{here}没有任何资料曾为与之用词足够相近的作品加过标记。", "hi" to "इससे यह पता नहीं चलता कि इसे किसी व्यक्ति ने लिखा या नहीं। इसका अर्थ है कि {here} किसी प्रोफ़ाइल ने ऐसा काम मुहरबंद नहीं किया जिसकी शब्दावली इससे पर्याप्त मेल खाती हो।", "ar" to "هذا لا يقول شيئًا عمّا إذا كان قد كتبه إنسان. إنه يقول إنه ما من ملف {here} ختم عملًا يشترك معه في ما يكفي من الصياغة."),
